sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-header {
  width: 100%;
  background: #1f3a30;
  color: #ffffff;
  padding: 18px 5%;
  box-sizing: border-box;
  font-family: Arial, sans-serif;
}

.hotel-header-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.hotel-brand {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: #ffffff;
  flex-shrink: 0;
}

.brand-name {
  font-family: Georgia, serif;
  font-size: 25px;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.brand-subtitle {
  color: #e6c79c;
  font-size: 9px;
  letter-spacing: 2.5px;
  margin-top: 4px;
}

.hotel-navigation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 28px;
}

.hotel-navigation a {
  color: #ffffff;
  text-decoration: none;
  font-size: 13px;
  transition: color 0.2s ease;
}

.hotel-navigation a:hover {
  color: #e6c79c;
}

.hotel-login {
  background: #e6c79c;
  color: #1f3a30;
  text-decoration: none;
  padding: 11px 24px;
  border-radius: 4px;
  font-size: 13px;
  font-weight: bold;
  white-space: nowrap;
  transition: background 0.2s ease;
}

.hotel-login:hover {
  background: #d4b07c;
}

@media (max-width: 850px) {
  .hotel-header-inner {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hotel-navigation {
    flex-wrap: wrap;
    gap: 15px;
  }
}
